"""Chapter 6 Energy: written-answer questions, 5 per level."""
from .. import sketches
from ..marker import Pitfall, Point
from .base import written

P = Point
PF = Pitfall

# ---------------------------------------------------------------- L1
written("w6_store_moving_car", 6, 1, "6a",
        stem="Fig. 1 shows a car moving along a road. Name the energy store associated with its motion.",
        points=[P("kinetic energy store", ["kinetic"])],
        pitfalls=[PF(["potential"], "Potential energy is to do with position or shape. Energy of MOTION is kinetic.")],
        model_answer="The kinetic energy store.",
        hints=["Which store does every moving object have?",
               "It depends on mass and speed.",
               "It begins with k."],
        keywords="kinetic",
        figure=lambda: sketches.motion_sketch("", "", "moving", body_label="car"),
        sample_pass=["Kinetic energy", "its kinetic store"],
        sample_fail=["Gravitational potential energy", "chemical"])

written("w6_define_work", 6, 1, "6d",
        stem="State what is meant by the work done by a force.",
        points=[P("force × distance moved in the direction of the force",
                  ["force times distance", "force multiplied by distance", "force x distance", "force × distance", "product of force and distance", "force and the distance", "force by the distance"])],
        pitfalls=[PF(["force times time", "force multiplied by time", "force x time"], "Time is not part of work done. Work = force × distance moved in the direction of the force.")],
        model_answer="Work done = force × distance moved in the direction of the force.",
        hints=["Work is done when a force makes something move. Which two quantities are multiplied?",
               "A bigger force, or a longer distance, means more work.",
               "Work done = ___ × ___ moved in the direction of the force."],
        keywords="force × distance moved in the direction of the force",
        sample_pass=["Work done is the force multiplied by the distance moved in the direction of the force", "the product of force and distance moved"],
        sample_fail=["Force times time", "The energy of a moving object"])

written("w6_define_power", 6, 1, "6e",
        stem="Define power.",
        points=[P("rate of energy transfer / work done per unit time",
                  ["rate of energy transfer", "rate of doing work", "rate at which work", "rate at which energy", "energy transferred per second", "energy per unit time", "work done per second", "work done per unit time", "energy divided by time", "work divided by time", "energy transfer divided by time", "energy transferred divided by the time"])],
        pitfalls=[PF(["force times distance", "force multiplied by distance"], "That is work done. Power is how FAST work is done: energy ÷ time.")],
        model_answer="Power is the rate of energy transfer (or the rate of doing work): power = energy transferred ÷ time taken.",
        hints=["Power is about how QUICKLY energy is transferred.",
               "Energy (or work) divided by what?",
               "Power = energy transferred ÷ ___ ."],
        keywords="energy transferred ÷ time, rate of doing work",
        sample_pass=["The rate at which energy is transferred", "work done per second", "energy transfered divided by time taken"],
        sample_fail=["Force times distance", "How strong a machine is"])

written("w6_conservation_principle", 6, 1, "6c",
        stem="State the principle of conservation of energy.",
        points=[P("energy cannot be created or destroyed; it can only be transferred from one store to another",
                  ["cannot be created or destroyed", "neither created nor destroyed", "can not be created", "cannot be destroyed", "cannot be made or destroyed", "total energy is constant", "total energy stays the same", "total energy remains", "only transferred", "only be transferred", "converted from one"])],
        model_answer="Energy cannot be created or destroyed; it can only be transferred from one store to another, so the total energy of a closed system stays constant.",
        hints=["It is about the TOTAL amount of energy before and after any process.",
               "Energy moves between stores, but the total never changes.",
               "Energy cannot be ___ or ___; it can only be transferred."],
        keywords="cannot be created or destroyed, only transferred",
        sample_pass=["Energy cannot be created or destroyed, only transferred between stores", "the total energy stays the same, it is just converted from one form to another"],
        sample_fail=["Energy is always lost as heat", "Energy can be made by burning fuel"])

written("w6_unit_power", 6, 1, "6e",
        stem="State the SI unit of power and what it is equivalent to.",
        points=[P("watt, equal to one joule per second", ["watt", "joule per second", "j/s", "joules per second"])],
        pitfalls=[PF(["newton"], "The newton is the unit of force."), PF(["joule is the unit of power", "power is measured in joules"], "The joule is the unit of energy. Power is energy per second: the watt.")],
        model_answer="The watt (W); 1 W = 1 J/s, one joule of energy transferred per second.",
        hints=["Light bulbs and kettles are labelled with this unit.",
               "It is energy per second.",
               "The ___, equal to 1 joule per ___ ."],
        keywords="watt, 1 J/s",
        sample_pass=["The watt, which is one joule per second", "W = J/s"],
        sample_fail=["The joule", "newtons"])

# ---------------------------------------------------------------- L2
written("w6_gpe_factors", 6, 2, "6b",
        stem="Fig. 1 shows a box being lifted. State two quantities on which the gain in gravitational potential energy of the box depends.",
        points=[P("its mass (or weight)", ["mass", "weight", "heavier"]),
                P("the height it is raised through", ["height", "how high", "vertical distance", "distance lifted", "lifted through"])],
        pitfalls=[PF(["speed"], "Speed affects kinetic energy, not gravitational potential energy.")],
        model_answer="Its mass (and the gravitational field strength) and the height through which it is lifted: Ep = m g h.",
        hints=["Think of the formula Ep = m g h. Which letters can the person lifting change?",
               "Lifting something heavier, or lifting it higher, both store more energy.",
               "Its ___ and the ___ it is raised."],
        keywords="mass, height (Ep = mgh)",
        figure=lambda: sketches.lift_sketch("h", body_label="m"),
        sample_pass=["Its mass and the height it is lifted", "the weight of the box and how high it goes"],
        sample_fail=["Its speed and its volume", "The time taken"])

written("w6_ke_factors", 6, 2, "6b",
        stem="State the two quantities on which the kinetic energy of a moving object depends, and say which has the greater effect.",
        points=[P("its mass", ["mass"]),
                P("its speed, which has the greater effect because kinetic energy depends on speed squared", ["speed", "velocity", "squared", "square of", "doubling the speed", "four times", "greater effect", "bigger effect"])],
        model_answer="Kinetic energy depends on mass and on speed (Ek = ½ m v²). Speed has the greater effect, because doubling the speed quadruples the kinetic energy.",
        hints=["Look at Ek = ½ m v². Two quantities appear; one of them is squared.",
               "Doubling the mass doubles Ek. What does doubling the speed do?",
               "Mass and ___; the ___ matters more because it is squared."],
        keywords="mass, speed (squared)",
        sample_pass=["Mass and speed; speed has the bigger effect because it is squared", "it depends on mass and velocity, and doubling the velocity gives four times the energy"],
        sample_fail=["Mass and height", "Speed and time"])

written("w6_pendulum_transfers", 6, 2, "6c",
        stem="Fig. 1 shows a pendulum. Describe the energy transfers as the bob swings from its highest point down to its lowest point.",
        points=[P("gravitational potential energy decreases", ["potential energy decreases", "potential decreases", "loses potential", "potential energy falls", "potential energy is transferred", "gpe", "potential to kinetic", "potential energy to kinetic"]),
                P("kinetic energy increases, reaching a maximum at the lowest point", ["kinetic energy increases", "gains kinetic", "kinetic increases", "to kinetic", "maximum kinetic", "fastest at the bottom", "kinetic energy is greatest"])],
        model_answer="As the bob falls, its gravitational potential energy is transferred to kinetic energy: the potential energy decreases and the kinetic energy increases, reaching a maximum at the lowest point where the bob moves fastest.",
        hints=["Which store decreases as the bob loses height? Which increases as it speeds up?",
               "Height → gravitational potential energy; speed → kinetic energy.",
               "Gravitational ___ energy decreases; ___ energy increases."],
        keywords="gravitational potential energy → kinetic energy",
        figure=lambda: sketches.pendulum_sketch(),
        sample_pass=["Gravitational potential energy decreases and kinetic energy increases", "GPE is transferred to kinetic energy, which is a maximum at the bottom"],
        sample_fail=["The bob gets faster", "Energy is lost as it swings"])

written("w6_kettle_pathways", 6, 2, "6a",
        stem="An electric kettle is used to boil water. Name the pathway by which energy is transferred to the heating element, and the pathway by which energy is transferred from the element to the water.",
        points=[P("electrically (by an electric current) to the element", ["electrical", "electrically", "electric current", "current"]),
                P("by heating (due to a temperature difference) from the element to the water", ["heating", "by heating", "temperature difference", "conduction", "thermal"])],
        model_answer="Energy is transferred electrically (by the electric current) to the heating element, and then by heating from the hot element to the cooler water.",
        hints=["The syllabus names four pathways: mechanically, electrically, by heating, by waves. Pick the two used here.",
               "What flows into the element? What makes energy move from the hot element to the water?",
               "___ to the element; by ___ to the water."],
        keywords="electrically, by heating",
        sample_pass=["Electrically to the element and by heating to the water", "an electric current carries energy to the element, which then heats the water by conduction"],
        sample_fail=["Mechanically and by waves", "The water boils"])

written("w6_falling_ball", 6, 2, "6c",
        stem="A ball is dropped from a window. Describe the energy changes that take place before it reaches the ground (ignore air resistance).",
        points=[P("gravitational potential energy decreases", ["potential energy decreases", "potential decreases", "loses potential", "potential energy falls", "gpe", "potential to kinetic", "potential energy to kinetic"]),
                P("kinetic energy increases as the ball speeds up", ["kinetic energy increases", "gains kinetic", "kinetic increases", "to kinetic", "speeds up"])],
        pitfalls=[PF(["energy is lost", "energy is destroyed", "loses energy"], "With no air resistance no energy is lost: the potential energy becomes kinetic energy, so the total stays the same.")],
        model_answer="As the ball falls, its gravitational potential energy decreases and is transferred to kinetic energy, which increases as the ball speeds up. The total energy stays constant.",
        hints=["The ball loses height and gains speed. Name the store for each.",
               "Height → gravitational potential energy; speed → kinetic energy.",
               "___ energy decreases, ___ energy increases."],
        keywords="gravitational potential energy decreases, kinetic energy increases",
        sample_pass=["Gravitational potential energy decreases while kinetic energy increases", "GPE is transferred to kinetic energy as it speeds up"],
        sample_fail=["The ball loses energy as it falls", "It gets faster"])

# ---------------------------------------------------------------- L3
written("w6_bounce_lower", 6, 3, "6c",
        stem="Fig. 1 shows a ball dropped from 2.0 m that bounces back only to 1.2 m. Explain, using the principle of conservation of energy, why it does not return to 2.0 m.",
        points=[P("some energy is transferred to the internal (thermal) stores of the ball and ground", ["internal", "thermal", "heat", "warms", "temperature", "hotter"]),
                P("and to the surroundings as sound", ["sound"]),
                P("so less kinetic energy is left to convert back to gravitational potential energy; no energy is destroyed", ["less kinetic", "less energy left", "less potential", "lower height", "not destroyed", "total is the same", "conserved", "not lost"])],
        min_points=2,
        pitfalls=[PF(["energy is destroyed", "energy disappears", "energy is lost forever"], "Energy is never destroyed. It is transferred to other stores (thermal, sound).")],
        model_answer="When the ball hits the ground, some of its kinetic energy is transferred to the internal (thermal) stores of the ball and the ground and some is carried away as sound. Less kinetic energy remains to be transferred back to gravitational potential energy, so the ball rises to a lower height. The total energy is still conserved.",
        hints=["The ball has less gravitational potential energy at the top of the bounce. Energy is conserved, so where did the rest go?",
               "Think about what happens when the ball squashes against the floor: warming and a noise.",
               "Energy goes to ___ stores and ___; none is destroyed."],
        keywords="internal (thermal) store, sound, energy conserved",
        figure=lambda: sketches.lift_sketch("2.0 m", body_label="ball", extra="bounces back to 1.2 m"),
        sample_pass=["Some of the energy is transferred to thermal energy of the ball and ground and to sound, so less is left to lift the ball",
                     "energy is not destroyed but some goes into warming the ball and making a sound, leaving less kinetic energy"],
        sample_fail=["Energy is destroyed on impact", "Gravity gets stronger"])

written("w6_car_braking_energy", 6, 3, "6d",
        stem="A moving car brakes and comes to rest. Explain what happens to its kinetic energy.",
        points=[P("the brakes / friction do work on the car", ["friction", "brakes do work", "work is done", "work done by", "braking force"]),
                P("the kinetic energy is transferred to the internal (thermal) store of the brakes and tyres, which warm up", ["internal", "thermal", "heat", "warm", "hot", "temperature"]),
                P("some is transferred as sound; the total energy is conserved", ["sound", "conserved", "not destroyed", "total"])],
        min_points=2,
        pitfalls=[PF(["energy is destroyed", "energy disappears"], "The kinetic energy is not destroyed; friction transfers it to thermal stores.")],
        model_answer="Friction between the brake pads and the wheels does work on the car. The kinetic energy is transferred mainly to the internal (thermal) stores of the brakes, tyres and road, which warm up, and a little as sound. The total energy is conserved.",
        hints=["Something must do work on the car to slow it. What force is that?",
               "Friction makes things hot. Which store gains the energy?",
               "___ does work; kinetic energy → ___ store (brakes get hot)."],
        keywords="friction does work, internal (thermal) store, brakes warm up",
        sample_pass=["Friction in the brakes does work and transfers the kinetic energy to thermal energy, so the brakes get hot", "the braking force does work, converting the kinetic energy into heat and some sound"],
        sample_fail=["The kinetic energy is destroyed", "The car stops because the engine turns off"])

written("w6_cyclist_hill", 6, 3, "6d",
        stem="Explain why a cyclist has to do more work to travel 100 m up a hill than 100 m along a flat road at the same steady speed.",
        points=[P("going uphill the cyclist gains gravitational potential energy / does work against gravity", ["potential energy", "against gravity", "gains height", "lifts", "work against the weight", "raise"]),
                P("in addition to the work done against friction and air resistance in both cases", ["friction", "air resistance", "as well", "in addition", "also", "both cases"])],
        model_answer="On both routes the cyclist does work against friction and air resistance. Going uphill the cyclist also does work against gravity, gaining gravitational potential energy, so the total work done is greater.",
        hints=["What is different about the two journeys in terms of height?",
               "Gaining height means gaining which energy store? Who has to supply it?",
               "Uphill: extra work against ___ (gains ___ energy) on top of friction and air resistance."],
        keywords="work against gravity, gravitational potential energy, plus friction and air resistance",
        sample_pass=["Going uphill the cyclist gains gravitational potential energy as well as working against friction and air resistance",
                     "work must be done against gravity to raise the bike, in addition to the friction present on both roads"],
        sample_fail=["Hills are harder", "The bike is heavier on a hill"])

written("w6_two_students_stairs", 6, 3, "6e",
        stem="Two students of equal mass run up the same flight of stairs. Student A takes 5 s and student B takes 8 s. Compare the work they do and their power.",
        points=[P("they do the same work (same weight lifted through the same height)", ["same work", "equal work", "same amount of work", "same energy", "equal energy", "same mgh", "same height"]),
                P("A has the greater power because the same energy is transferred in a shorter time", ["a has more power", "a greater power", "a higher power", "a is more powerful", "a has the greater", "shorter time", "less time", "faster"])],
        pitfalls=[PF(["a does more work", "a did more work", "b does more work", "b did more work"], "Work done = weight × height, which is the same for both. Only the POWER differs.")],
        model_answer="Both students do the same work, because they lift the same weight through the same height. Student A has the greater power, because the same energy is transferred in a shorter time (power = work ÷ time).",
        hints=["Work done = force × distance. Is anything different about the force or the height for A and B?",
               "Power = work ÷ time. Who took less time?",
               "Same ___; A has the greater ___ ."],
        keywords="same work done, A greater power",
        sample_pass=["They do the same work but A has more power because A took less time", "equal work, as the height and weight are the same; A is more powerful"],
        sample_fail=["A does more work because A ran faster", "B has more power because B took longer"])

written("w6_slope_friction_loss", 6, 3, "6c",
        stem="Fig. 1 shows a trolley released from rest at the top of a rough slope. At the bottom its kinetic energy is less than the gravitational potential energy it lost. Explain why.",
        points=[P("work is done against friction on the slope", ["friction", "work against friction", "frictional force"]),
                P("so some energy is transferred to the internal (thermal) store of the trolley and slope", ["internal", "thermal", "heat", "warm", "hot", "temperature"]),
                P("leaving less energy to become kinetic energy; energy is conserved overall", ["less kinetic", "less energy left", "conserved", "not destroyed", "total", "remaining"])],
        min_points=2,
        pitfalls=[PF(["energy is destroyed", "energy disappears"], "Energy is never destroyed. Friction transfers some of it to thermal stores.")],
        model_answer="The slope is rough, so work is done against friction as the trolley slides down. Some of the gravitational potential energy is transferred to the internal (thermal) stores of the trolley and slope, so less is transferred to kinetic energy. The total energy is still conserved.",
        hints=["The slope is rough. Which force acts against the motion, and what does it do with energy?",
               "Friction transfers energy to thermal stores: things warm up.",
               "Work done against ___ → energy to ___ store → less ___ energy."],
        keywords="friction, internal (thermal) store, less kinetic energy",
        figure=lambda: sketches.slope_sketch("h", top_label="released from rest", bottom_label="rough slope"),
        sample_pass=["Work is done against friction so some energy goes into heating the slope and trolley, leaving less kinetic energy",
                     "friction transfers some of the energy to the thermal store so not all the potential energy becomes kinetic"],
        sample_fail=["Energy is destroyed on the slope", "The trolley is heavy"])

# ---------------------------------------------------------------- L4
written("w6_roller_coaster", 6, 4, "6c",
        stem="Fig. 1 shows a roller-coaster car released from rest at the top of the first hill. Explain why, without a motor, it can never climb to a point higher than its starting point.",
        points=[P("its energy comes only from the gravitational potential energy it had at the start", ["gravitational potential", "potential energy at the start", "starting energy", "initial energy", "only the energy", "no energy input", "no extra energy"]),
                P("friction and air resistance transfer some of this energy to internal (thermal) stores", ["friction", "air resistance", "internal", "thermal", "heat"]),
                P("so the energy available to regain height is less than at the start; energy cannot be created", ["less", "cannot reach", "lower", "cannot be created", "conserved", "not enough energy", "reduced"])],
        min_points=2,
        model_answer="The car starts with a fixed amount of gravitational potential energy and no other energy input. As it moves, friction and air resistance transfer some of that energy to internal (thermal) stores. The mechanical energy left to be converted back into gravitational potential energy is therefore less than at the start, so it cannot reach a greater height; energy cannot be created.",
        hints=["Where does all of the car's energy come from, and can any be added without a motor?",
               "Friction and air resistance act all the way round. What do they do with energy?",
               "Fixed starting ___ energy; some goes to ___ stores; so less is available to gain height."],
        keywords="fixed initial potential energy, friction and air resistance → thermal, less energy available",
        figure=lambda: sketches.slope_sketch("h", top_label="released from rest", bottom_label="to the next hill"),
        sample_pass=["It only has the potential energy it started with, and friction and air resistance transfer some to heat, so it has less energy to climb back up",
                     "no energy is added; friction converts part of the energy to thermal energy so the height it can reach is lower"],
        sample_fail=["Gravity pulls it down too hard", "It runs out of speed"])

